"use strict";
window.SquadTactical = (()=>{
 const definitions={...SquadAslDefinitions.types};
 const put=(ids,values,note)=>{for(const id of ids.split(' '))definitions[id]={definitionId:id,status:'provisional estimate',source:'Campaign Atlas role-based estimate v2',rationale:note||'Explicit playable ASL-style estimate, not an official ASL counter transcription. No Panzer combat factors copied.',values:{...values}};};
 const vehicle=(ids,name,move,mp,front,side,caliber,suffix,role)=>put(ids,{designation:name,'movement-type':move,'movement-points':mp,'af-front':front,'af-side':side,...(caliber?{caliber,'caliber-suffix':suffix,'rate-of-fire':1}:{}),'vehicle-role':role});
 vehicle('us-m4-75 uk-sherman','Sherman 75','fully-tracked',13,8,3,75,'','turreted tank');
 vehicle('us-m4-76','Sherman 76','fully-tracked',13,8,3,76,'l','turreted tank');
 vehicle('uk-firefly','Sherman Firefly','fully-tracked',13,8,3,76.2,'ll','turreted tank');
 vehicle('uk-cromwell-goodwood','Cromwell','fully-tracked',18,8,3,75,'','turreted tank');
 vehicle('us-m4-105','Sherman 105','fully-tracked',13,8,3,105,'star','turreted assault gun');
 vehicle('us-m5','M5 Stuart','fully-tracked',18,4,3,37,'l','turreted tank');
 vehicle('us-m24','M24 Chaffee','fully-tracked',18,4,2,75,'','turreted tank');
 vehicle('de-pziv-w de-pziv','Panzer IV H','fully-tracked',12,8,3,75,'l','turreted tank');
 vehicle('de-panther-w de-panther','Panther','fully-tracked',15,18,6,75,'ll','turreted tank');
 vehicle('de-tiger','Tiger I','fully-tracked',11,11,8,88,'l','turreted tank');
 vehicle('de-kingtiger','Tiger II','fully-tracked',11,26,8,88,'ll','turreted tank');
 vehicle('de-pziii','Panzer III J','fully-tracked',13,6,3,50,'l','turreted tank');
 vehicle('de-lynx','Pz II L Lynx','fully-tracked',18,3,1,20,'l','turreted reconnaissance tank');
 vehicle('de-hetzer','Hetzer','fully-tracked',13,11,3,75,'l','fixed-mount tank destroyer');
 vehicle('de-stug','StuG III','fully-tracked',14,8,3,75,'l','fixed-mount assault gun');
 vehicle('us-m10','M10','fully-tracked',12,4,2,76,'l','open-top tank destroyer');
 vehicle('us-m18','M18 Hellcat','fully-tracked',24,2,1,76,'l','open-top tank destroyer');
 vehicle('us-m36','M36','fully-tracked',13,4,2,90,'l','open-top tank destroyer');
 vehicle('uk-achilles be-achilles','Achilles','fully-tracked',12,4,2,76.2,'ll','open-top tank destroyer');
 vehicle('uk-sexton','Sexton','fully-tracked',13,2,1,87.6,'star','open-top self-propelled artillery');
 vehicle('us-m7','M7 Priest','fully-tracked',12,4,1,105,'star','open-top self-propelled artillery');
 vehicle('de-wespe','Wespe','fully-tracked',12,2,1,105,'star','open-top self-propelled artillery');
 vehicle('de-hummel','Hummel','fully-tracked',13,2,1,150,'star','open-top self-propelled artillery');
 vehicle('de-grille','Grille','fully-tracked',12,2,1,150,'star','open-top self-propelled infantry gun');
 vehicle('de-maultier-goodwood','Maultier rocket launcher','half-tracked',12,1,1,150,'','self-propelled rocket artillery');
 vehicle('de-234-1','SdKfz 234/1','armored-car',30,2,1,20,'l','armored reconnaissance');
 vehicle('de-234-2','SdKfz 234/2 Puma','armored-car',30,3,1,50,'l','armored reconnaissance');
 vehicle('de-234-4','SdKfz 234/4','armored-car',30,2,1,75,'l','open-top gun carrier');
 vehicle('us-m8','M8 armored car','armored-car',30,1,1,37,'l','armored reconnaissance');
 vehicle('uk-daimler be-daimler','Daimler armored car','armored-car',30,1,1,40,'l','armored reconnaissance');
 vehicle('us-m20','M20 scout car','armored-car',30,1,1,0,'','scout transport');
 vehicle('uk-m3','M3 scout car','armored-car',28,1,1,0,'','scout transport');
 vehicle('uk-daimler-scout','Daimler scout car','armored-car',30,1,1,0,'','scout transport');
 vehicle('uk-bren ca-bren be-bren uk-mgcarrier','Bren carrier','fully-tracked',16,1,1,0,'','weapon carrier');
 vehicle('uk-valentine-bridge-carrier','Valentine bridgelayer','fully-tracked',10,6,3,0,'','unarmed bridge carrier');
 vehicle('us-m16','M16 AA halftrack','half-tracked',16,1,1,0,'','quad machine-gun AA');
 vehicle('de-wirbelwind','Wirbelwind','fully-tracked',12,8,3,20,'l','quad cannon AA');
 // Transport, MG and special properties are explicit and limited to applicable roles.
 for(const id of ['uk-bren','ca-bren','be-bren','uk-mgcarrier'])Object.assign(definitions[id].values,{'passenger-capacity':5,'aamg':2});
 for(const id of ['us-m20','uk-m3','uk-daimler-scout'])Object.assign(definitions[id].values,{'aamg':2});
 Object.assign(definitions['us-m16'].values,{ife:12,'rate-of-fire':2});
 Object.assign(definitions['de-wirbelwind'].values,{ife:12,'rate-of-fire':2});
 put('us-halftrack',{designation:'M3 halftrack','movement-type':'half-tracked','movement-points':16,'af-front':1,'af-side':1,'passenger-capacity':15,aamg:3});
 put('us-truck uk-truck ca-truck be-truck',{designation:'Allied truck','movement-type':'truck','movement-points':30,'passenger-capacity':12,towing:7});
 put('de-wagon',{designation:'Horse-drawn wagon','movement-type':'wagon','movement-points':8,'passenger-capacity':10});
 const gun=(ids,name,kind,cal,suffix,rof,mh,extra={})=>put(ids,{designation:name,'gun-type':kind,caliber:cal,'caliber-suffix':suffix,'rate-of-fire':rof,manhandling:mh,...extra});
 gun('us-57mm uk-6pdr ca-6pdr','57 mm / 6-pounder AT','at',57,'l',3,8);
 gun('us-76mm','3-inch M5 AT','at',76,'l',2,7);
 gun('us-90mm','90 mm M2','aa',90,'l',2,5);
 gun('de-75mm','75 mm PaK 40','at',75,'l',2,8);
 gun('de-88mm','88 mm gun','at',88,'l',2,5);
 gun('us-40mm','40 mm Bofors','aa',40,'l',2,10,{ife:8});
 gun('de-20mm','20 mm AA','aa',20,'l',3,12,{ife:4});
 gun('de-quad20','Quad 20 mm AA','aa',20,'l',2,10,{ife:12});
 gun('de-37mm','37 mm AA','aa',37,'l',2,10,{ife:6});
 gun('uk-25pdr ca-25pdr be-25pdr','25-pounder','art',87.6,'',2,8);
 gun('de-75how','75 mm howitzer','art',75,'star',2,9);
 gun('de-105how us-105mm','105 mm howitzer','art',105,'',2,6);
 gun('de-150how','150 mm howitzer','art',150,'',1,4);
 gun('us-155mm','155 mm howitzer','art',155,'',1,4);
 gun('us-8inch','8-inch gun','art',203,'',1,3);
 gun('de-170how','170 mm K18','art',170,'l',1,3);
 gun('de-150ig','150 mm infantry gun','inf',150,'star',1,7);
 gun('de-nebel','150 mm Nebelwerfer','rocket',150,'',1,7,{'indirect-fire':true});
 for(const [ids,cal,rof,mh] of [['us-81mm uk-81mm de-81mm',81,3,11],['ca-76mortar be-76mortar',76,3,11],['ca-107mortar',107,2,8],['de-120mm',120,2,8]])gun(ids,cal+' mm mortar','mtr',cal,'',rof,mh,{'range-minimum':3,'range-maximum':60,traits:['asl:no-ap']});
 put('ca-mg',{designation:'Commonwealth machine-gun team',size:'medium',firepower:4,range:10,'rate-of-fire':2,breakdown:12,portage:4},'Commonwealth MG estimate; the original Allied composition row is retained separately, including its .50-cal description.');
 // A catalog weapon value does not establish a whole formation's organization.
 for(const [id,def] of Object.entries(definitions))if(SquadProfiles.types[id]?.kind==='equipment')definitions[id]={...def,values:{}};
 window.SquadAslDefinitions={...SquadAslDefinitions,libraryVersion:'role-estimates-2',types:definitions};
 const member=(typeId,index)=>SquadProfiles.types[typeId]?.members?.[index]||{definitionId:typeId,label:SquadProfiles.types[typeId]?.label};
 const definition=(typeId,unit)=>definitions[unit?.definitionId||typeId];
 return {member,definition};
})();
